1	package retention
2	
3	import (
4		"bytes"
5		"encoding/json"
6		"errors"
7		"fmt"
8		"os"
9		"path/filepath"
10		"sort"
11		"strings"
12		"sync"
13		"syscall"
14	)
15	
16	// 状态文件与锁文件的固定名称，位于调用者选择的本地目录内。
17	const (
18		stateFileName = "retention-state.json"
19		lockFileName  = ".retention.lock"
20	)
21	
22	// Store 是一个本地保管库，对应调用者选择的一个本地保存位置。
23	//
24	// 同一个目录可以被本机上的多个程序（进程）同时打开：
25	// 每次办理都会取得跨进程的排他文件锁，并从磁盘重新读取状态，
26	// 因此两个程序对同一档案的冻结、销毁一定有明确的先后顺序。
27	type Store struct {
28		dir string
29	
30		// opMu 串行化当前 Store 实例内的办理；跨进程互斥由文件锁保证。
31		opMu sync.RWMutex
32	}
33	
34	// Open 打开（或创建）一个本地保存位置。
35	// 目录不存在时会创建；状态文件不存在时按空库打开，可以正常登记。
36	// 状态文件已存在但内容损坏（空文件、只有空白、内容为 null、合法对象后面
37	// 还拼接了其他内容等），或其中保存的记录不满足业务不变量（例如已解除冻结
38	// 缺少解除原因或解除日期、解除日期早于冻结日期、已销毁档案与已关闭清册
39	// 对应不上、已关闭清册缺少处理日期、清册处理日期早于所收录档案销毁时最终
40	// 生效的保管截止日（提前销毁）、已关闭清册条目保存的类别、起算日或截止日
41	// （须为销毁时最终生效的期限）与档案登记内容不一致、修订记录衔接不上、
42	// 成功修订编号在保存历史中不唯一或与已关闭清册的申请编号相同）时返回
43	// ErrCorruptState，不会返回可继续办理的保管库，已有记录保持原样，不会被
44	// 清空、修补或覆盖。
45	func Open(dir string) (*Store, error) {
46		if dir == "" {
47			return nil, errors.New("retention: 保存位置不能为空")
48		}
49		if err := os.MkdirAll(dir, 0o755); err != nil {
50			return nil, fmt.Errorf("retention: 无法创建保存位置: %w", err)
51		}
52		s := &Store{dir: dir}
53		// 提前读一次，让损坏的状态文件在打开时就暴露，而不是等到第一次办理。
54		if _, err := s.load(); err != nil {
55			return nil, err
56		}
57		return s, nil
58	}
59	
60	// Close 释放保管库。当前实现没有跨操作持有的资源，保留它以稳定公开入口形态。
61	func (s *Store) Close() error { return nil }
62	
63	func (s *Store) statePath() string { return filepath.Join(s.dir, stateFileName) }
64	func (s *Store) lockPath() string  { return filepath.Join(s.dir, lockFileName) }
65	
66	// lock 取得跨进程排他锁，返回解锁函数。
67	// 每次办理各自加锁、解锁，这样同一位置也允许同进程或跨进程的多个 Store 并存。
68	func (s *Store) lock() (func(), error) {
69		f, err := os.OpenFile(s.lockPath(), os.O_CREATE|os.O_RDWR, 0o600)
70		if err != nil {
71			return nil, fmt.Errorf("retention: 无法打开锁文件: %w", err)
72		}
73		if err := syscall.Flock(int(f.Fd()), syscall.LOCK_EX); err != nil {
74			f.Close()
75			return nil, fmt.Errorf("retention: 无法取得保存位置锁: %w", err)
76		}
77		return func() {
78			_ = syscall.Flock(int(f.Fd()), syscall.LOCK_UN)
79			_ = f.Close()
80		}, nil
81	}
82	
83	// rlock 取得跨进程共享锁，用于只读核对。
84	func (s *Store) rlock() (func(), error) {
85		f, err := os.OpenFile(s.lockPath(), os.O_CREATE|os.O_RDWR, 0o600)
86		if err != nil {
87			return nil, fmt.Errorf("retention: 无法打开锁文件: %w", err)
88		}
89		if err := syscall.Flock(int(f.Fd()), syscall.LOCK_SH); err != nil {
90			f.Close()
91			return nil, fmt.Errorf("retention: 无法取得保存位置锁: %w", err)
92		}
93		return func() {
94			_ = syscall.Flock(int(f.Fd()), syscall.LOCK_UN)
95			_ = f.Close()
96		}, nil
97	}
98	
99	// load 从磁盘读取最新状态。文件不存在时返回一份空状态（尚未建立记录）。
100	//
101	// 文件已经存在时，必须完整包含且只包含一个 JSON 对象（前后允许空白）：
102	// 零字节或只有空白的文件、内容为 null 的文件、合法对象后面还拼接了
103	// 第二个 JSON 值或无法解析的文字，都判为损坏并返回 ErrCorruptState，
104	// 绝不只使用前一段内容，也不会改动原文件。
105	//
106	// JSON 能解析不代表记录合法：任何已解除冻结都必须同时带有非空白的
107	// 解除原因和有效的解除日期，且解除日期不早于冻结日期——与解除功能
108	// 办理时的要求一致。缺少任一信息或日期顺序不成立时，整份保管库同样
109	// 判为损坏并返回 ErrCorruptState，错误信息指明涉及的档案与冻结编号。
110	//
111	// 已销毁档案与已关闭清册也必须相互对应：每份已销毁档案记下的申请编号
112	// 必须能找到一份清册，且该清册恰好收录该档案一次；清册收录的每份档案
113	// 也必须存在、标成已销毁并指回这份清册。已销毁档案找不到清册、同一档案
114	// 出现在多份清册、归属指向别的申请，或未销毁档案仍挂有清册申请编号，
115	// 都说明记录已无法说明档案由哪次申请销毁，整份保管库判为损坏并返回
116	// ErrCorruptState，错误信息指明涉及的档案编号与相关申请编号。
117	//
118	// 仅归属对应还不够：已关闭清册中的每条档案条目是销毁成功那一刻登记内容
119	// 的快照，其类别、起算日、截止日必须与对应档案当前保存的登记内容逐项
120	// 一致。档案销毁后期限不能再修订，编号、类别与起算日也从不改动，所以
121	// 合法记录中两处必然相同；截止日必须是销毁时最终生效的期限（最后一次
122	// 成功修订的新截止日，没有修订时为最初登记的截止日），即使修订历史衔接
123	// 完整、清册归属正确，保存成最初登记的截止日也属损坏。任一条目在类别、
124	// 起算日、截止日任一项上不一致，两处记录就互相矛盾，整份保管库判为
125	// 损坏并返回 ErrCorruptState，错误信息指明清册申请编号、档案编号与
126	// 不一致的项目；绝不挑选其中一处作为可信记录，也不通过覆盖清册、修改
127	// 档案或删除记录消除差异。一份清册收录多份档案时，一份条目矛盾就使
128	// 整份保管库无法读取，不会返回其余条目的正常结果。
129	//
130	// 清册的处理日期也必须满足办理销毁时同一条到期规则：每份已关闭清册都必须
131	// 带有处理日期，且处理日期不能早于其任一条目档案销毁时最终生效并保存到
132	// 清册里的截止日——截止日当天即到期，等于截止日或晚于截止日才合法。
133	// 缺少处理日期（字段缺失或为 null）不能当成已经办理的销毁日期；处理日期
134	// 早于某份档案的截止日属于提前销毁，即使该档案标记为已销毁、清册归属与
135	// 条目快照都一致，也说明销毁在到期前发生，两份记录无法同时成立。期限有过
136	// 修订的档案按清册条目保存的最终截止日判断（修订办理日期只记录办理时间，
137	// 不用它重新选择期限）。缺处理日期时错误指出申请编号；提前销毁时同时指出
138	// 申请编号、档案编号、处理日期与截止日。一份清册中只要有一份档案未到期，
139	// 整份保管库都判为损坏，不会只返回其余已到期档案的正常记录，也不会略过
140	// 未到期条目。
141	//
142	// 最初截止日、修订记录与当前截止日也必须连续对应：第一条修订的原截止日
143	// 等于最初截止日，后续每条的原截止日等于上一条的新截止日，最后一条的
144	// 新截止日等于当前截止日；没有修订时最初截止日与当前截止日相同。修订
145	// 日期仅用于记录，历史不按该日期重新排列。出现断开的修订关系、当前截止日
146	// 与末次修订不符、修订列表中存在空记录，或已有修订却缺少最初截止日时，
147	// 两个日期中任何一个都不能当作可靠依据，整份保管库判为损坏并返回
148	// ErrCorruptState，错误信息指明涉及的档案编号，能对应到具体修订时
149	// 同时指明修订编号。
150	//
151	// 每个成功修订编号在整个保管库内只能对应一条保存的修订记录，且不能与
152	// 已关闭清册的申请编号相同——与办理时“修订编号全库唯一、与销毁申请编号
153	// 互不占用”的要求一致。同一档案历史中重复出现同一编号、不同档案各自保存
154	// 同号修订（即使两条记录内容完全相同），或某条修订的编号与一份已关闭
155	// 清册的申请编号相同，都无法仅凭编号唯一确定应取回哪条修订，整份保管库
156	// 判为损坏并返回 ErrCorruptState；绝不合并记录或挑选其中一条继续使用。
157	// 错误信息指明冲突编号：同档案重复时指出该档案，跨档案重复时指出两份
158	// 档案，与清册冲突时指出修订所属档案与清册申请编号。
159	func (s *Store) load() (*storeData, error) {
160		raw, err := os.ReadFile(s.statePath())
161		if err != nil {
162			if errors.Is(err, os.ErrNotExist) {
163				return newStoreData(), nil
164			}
165			return nil, fmt.Errorf("retention: 无法读取状态文件: %w", err)
166		}
167		trimmed := bytes.TrimSpace(raw)
168		if len(trimmed) == 0 {
169			return nil, fmt.Errorf("retention: 状态文件为空或只有空白: %w", ErrCorruptState)
170		}
171		// json.Unmarshal 对 null 不报错且保持目标不变，必须单独拒绝。
172		if string(trimmed) == "null" {
173			return nil, fmt.Errorf("retention: 状态文件内容为 null，不是有效的保管库记录: %w", ErrCorruptState)
174		}
175		data := newStoreData()
176		// json.Unmarshal 要求整个输入恰好是一个 JSON 值：
177		// 合法对象后面再拼接任何内容都会在这里报错。
178		if err := json.Unmarshal(raw, data); err != nil {
179			return nil, fmt.Errorf("retention: 状态文件内容无法解析: %v: %w", err, ErrCorruptState)
180		}
181		if data.Archives == nil {
182			data.Archives = map[string]*archiveRecord{}
183		}
184		if data.Manifests == nil {
185			data.Manifests = map[string]*manifestRecord{}
186		}
187		// 语义校验先于任何兼容处理：已解除冻结必须与既有解除功能遵守同一要求——
188		// 解除原因与解除日期齐备，且解除日期不早于冻结日期。
189		// 只有“已解除”标记而缺少任一信息，或解除日期早于冻结日期的记录
190		// 一律判为损坏（即使所属档案已销毁）；绝不据此继续办理或修补记录。
191		if err := validateFreezeReleaseRecords(data); err != nil {
192			return nil, err
193		}
194		// 已销毁档案与已关闭清册必须相互对应，否则无法说明档案由哪次申请销毁。
195		// 关系损坏时绝不挑选其中一份记录继续使用，也不补清册或改销毁标记。
196		if err := validateManifestConsistency(data); err != nil {
197			return nil, err
198		}
199		// 兼容引入修订功能之前保存的保管库：没有修订记录也没有最初截止日时，
200		// 登记截止日就是最初截止日。已有修订却缺少最初截止日的记录不能据此
201		// 冒充，由 validateRevisionContinuity 按损坏拒绝。
202		for _, ar := range data.Archives {
203			if ar != nil && len(ar.Revisions) == 0 && ar.InitialEnd.IsZero() {
204				ar.InitialEnd = ar.End
205			}
206		}
207		// 已关闭清册中的每条档案条目是销毁成功那一刻的登记内容快照，
208		// 其类别、起算日与截止日必须与对应档案保存的登记内容逐项一致，
209		// 截止日必须是该档案销毁时最终生效的期限，不能拿最初登记的截止日顶替。
210		if err := validateManifestSnapshots(data); err != nil {
211			return nil, err
212		}
213		// 已关闭清册还必须带有处理日期，且处理日期不能早于任一条目档案销毁时
214		// 最终生效并保存到清册里的截止日——与办理销毁时的到期判断同一条规则。
215		if err := validateManifestProcessing(data); err != nil {
216			return nil, err
217		}
218		// 最初截止日、修订记录与当前截止日必须连续衔接，否则当前期限与
219		// 历史期限相互矛盾，任何一个日期都不能当作核对依据。
220		if err := validateRevisionContinuity(data); err != nil {
221			return nil, err
222		}
223		// 成功修订编号在整个保管库内只能对应一条保存的修订记录，且不能与
224		// 已关闭清册的申请编号相同——与办理时全库唯一、编号互不占用的要求一致。
225		if err := validateRevisionIDs(data); err != nil {
226			return nil, err
227		}
228		return data, nil
229	}
230	
231	// validateFreezeReleaseRecords 检查库内全部已解除冻结记录是否完整合法。
232	//
233	// 正常解除保存的记录必然同时带有非空白的解除原因和有效的解除日期，
234	// 且解除日期不早于冻结日期。缺少解除原因、解除日期缺失或为 null、
235	// 解除日期早于冻结日期，都说明保存内容已损坏，返回可由 ErrCorruptState
236	// 识别的错误，并在信息中给出涉及的档案编号与冻结编号，便于定位记录。
237	// 校验覆盖整个保管库的全部已解除冻结，与本次办理名单无关：
238	// 即使异常记录所属档案已经销毁，也不能把不完整的解除信息当作正常历史。
239	// 未解除冻结没有解除日期和原因是合法状态，不在此报错。
240	func validateFreezeReleaseRecords(data *storeData) error {
241		// map 遍历顺序不稳定，按档案编号排序后再检查，保证错误信息稳定。
242		archiveIDs := make([]string, 0, len(data.Archives))
243		for id := range data.Archives {
244			archiveIDs = append(archiveIDs, id)
245		}
246		sort.Strings(archiveIDs)
247		for _, id := range archiveIDs {
248			ar := data.Archives[id]
249			if ar == nil {
250				return fmt.Errorf("retention: 档案 %s 的登记记录缺失，状态文件已损坏: %w",
251					id, ErrCorruptState)
252			}
253			for _, fr := range ar.Freezes {
254				if fr == nil {
255					return fmt.Errorf("retention: 档案 %s 下存在缺失的冻结记录，状态文件已损坏: %w",
256						id, ErrCorruptState)
257				}
258				if !fr.Released {
259					// 未解除冻结没有解除日期与原因是合法状态。
260					continue
261				}
262				switch {
263				case strings.TrimSpace(fr.ReleaseReason) == "":
264					return fmt.Errorf(
265						"retention: 档案 %s 的冻结 %s 标记为已解除但缺少解除原因，记录已损坏: %w",
266						id, fr.ID, ErrCorruptState)
267				case fr.ReleasedOn == nil:
268					return fmt.Errorf(
269						"retention: 档案 %s 的冻结 %s 标记为已解除但缺少解除日期，记录已损坏: %w",
270						id, fr.ID, ErrCorruptState)
271				case fr.ReleasedOn.IsZero():
272					return fmt.Errorf(
273						"retention: 档案 %s 的冻结 %s 的解除日期无效，记录已损坏: %w",
274						id, fr.ID, ErrCorruptState)
275				case fr.ReleasedOn.Before(fr.FrozenOn):
276					return fmt.Errorf(
277						"retention: 档案 %s 的冻结 %s 的解除日期 %s 早于冻结日期 %s，记录已损坏: %w",
278						id, fr.ID, fr.ReleasedOn, fr.FrozenOn, ErrCorruptState)
279				}
280			}
281		}
282		return nil
283	}
284	
285	// validateManifestConsistency 检查已销毁档案与已关闭清册之间的对应关系。
286	//
287	// 正常销毁保存的记录必然满足双向对应：每份已销毁档案记下的申请编号
288	// 能找到一份清册，且该清册恰好收录该档案一次；清册收录的每份档案都
289	// 存在、标成已销毁，并指回这份清册。已销毁档案没有清册归属、归属的
290	// 清册不存在或未收录该档案、同一档案出现在多份清册、清册重复收录同一
291	// 档案、清册收录了不存在或未销毁的档案、档案归属指向别的申请，以及
292	// 未销毁档案仍挂有清册申请编号，都说明保存内容已损坏，返回可由
293	// ErrCorruptState 识别的错误，并在信息中给出涉及的档案编号与相关
294	// 申请编号，便于定位记录。校验覆盖整个保管库，与本次办理名单无关；
295	// 未销毁且没有清册归属的档案是合法记录，不在此报错。
296	func validateManifestConsistency(data *storeData) error {
297		// map 遍历顺序不稳定，按编号排序后再检查，保证错误信息稳定。
298		archiveIDs := make([]string, 0, len(data.Archives))
299		for id := range data.Archives {
300			archiveIDs = append(archiveIDs, id)
301		}
302		sort.Strings(archiveIDs)
303		for _, id := range archiveIDs {
304			ar := data.Archives[id]
305			if ar == nil {
306				// 缺失的登记记录已由 validateFreezeReleaseRecords 报告。
307				continue
308			}
309			if !ar.Destroyed {
310				if ar.ManifestID != "" {
311					return fmt.Errorf(
312						"retention: 档案 %s 未销毁却挂有清册申请编号 %s，记录已损坏: %w",
313						id, ar.ManifestID, ErrCorruptState)
314				}
315				continue
316			}
317			if ar.ManifestID == "" {
318				return fmt.Errorf(
319					"retention: 档案 %s 已销毁但没有记录所属清册的申请编号，记录已损坏: %w",
320					id, ErrCorruptState)
321			}
322			rec, ok := data.Manifests[ar.ManifestID]
323			if !ok || rec == nil {
324				return fmt.Errorf(
325					"retention: 档案 %s 已销毁，但其所属清册 %s 不存在，记录已损坏: %w",
326					id, ar.ManifestID, ErrCorruptState)
327			}
328			count := 0
329			for _, e := range rec.Entries {
330				if e.ID == id {
331					count++
332				}
333			}
334			if count != 1 {
335				return fmt.Errorf(
336					"retention: 档案 %s 在其所属清册 %s 中收录 %d 次（应恰好一次），记录已损坏: %w",
337					id, ar.ManifestID, count, ErrCorruptState)
338			}
339		}
340	
341		applicationIDs := make([]string, 0, len(data.Manifests))
342		for id := range data.Manifests {
343			applicationIDs = append(applicationIDs, id)
344		}
345		sort.Strings(applicationIDs)
346		for _, appID := range applicationIDs {
347			rec := data.Manifests[appID]
348			if rec == nil {
349				return fmt.Errorf(
350					"retention: 清册 %s 的内容缺失，记录已损坏: %w",
351					appID, ErrCorruptState)
352			}
353			seen := make(map[string]int, len(rec.Entries))
354			for _, e := range rec.Entries {
355				seen[e.ID]++
356				ar, ok := data.Archives[e.ID]
357				if !ok || ar == nil {
358					return fmt.Errorf(
359						"retention: 清册 %s 收录的档案 %s 不存在，记录已损坏: %w",
360						appID, e.ID, ErrCorruptState)
361				}
362				if !ar.Destroyed {
363					return fmt.Errorf(
364						"retention: 清册 %s 收录的档案 %s 未标记为已销毁，记录已损坏: %w",
365						appID, e.ID, ErrCorruptState)
366				}
367				if ar.ManifestID != appID {
368					return fmt.Errorf(
369						"retention: 清册 %s 收录的档案 %s 归属另一申请 %s，记录已损坏: %w",
370						appID, e.ID, ar.ManifestID, ErrCorruptState)
371				}
372			}
373			// 同一档案被同一份清册重复收录（档案侧的恰好一次检查只覆盖
374			// 归属指向该清册的情况，这里对全部收录记录再核对一遍）。
375			entryIDs := make([]string, 0, len(seen))
376			for id := range seen {
377				entryIDs = append(entryIDs, id)
378			}
379			sort.Strings(entryIDs)
380			for _, id := range entryIDs {
381				if seen[id] > 1 {
382					return fmt.Errorf(
383						"retention: 清册 %s 重复收录档案 %s（共 %d 次），记录已损坏: %w",
384						appID, id, seen[id], ErrCorruptState)
385				}
386			}
387		}
388		return nil
389	}
390	
391	// validateManifestSnapshots 检查每份已关闭清册中的档案条目是否与对应档案
392	// 当前保存的登记内容逐项一致。
393	//
394	// 清册在销毁成功那一刻关闭，条目是关闭瞬间登记内容的快照：档案销毁后
395	// 不能再修订期限，编号、类别与起算日也从不改动，因此合法记录中清册条目
396	// 的类别、起算日与截止日必然与对应档案保存的值相同——其中截止日必须是
397	// 该档案销毁时最终生效的期限（等于最后一次成功修订的新截止日；没有修订
398	// 时等于最初登记的截止日），不能拿最初登记的截止日顶替。延长、缩短或
399	// 改回曾经使用过的日期都沿用这一规则，不按修订记录中的办理日期重新选择。
400	//
401	// 任一条目在类别、起算日、截止日任一项上与档案不一致，两处记录就互相
402	// 矛盾，任何一处都不能当作可信依据：返回可由 ErrCorruptState 识别的错误，
403	// 绝不挑选其中一份继续使用，也不通过覆盖清册、修改档案或删除记录消除差异。
404	// 错误信息给出清册申请编号、档案编号与不一致的项目（类别、起算日、
405	// 保管截止日，并附上两处各自保存的值）。校验覆盖整个保管库的全部清册
406	// 与全部条目，与本次办理名单或查询目标无关：一份清册收录多份档案时，
407	// 只要有一份条目矛盾，整份保管库都判为损坏，不会返回其余条目的正常结果。
408	func validateManifestSnapshots(data *storeData) error {
409		// map 遍历顺序不稳定，按申请编号、条目顺序检查，保证错误信息稳定。
410		appIDs := make([]string, 0, len(data.Manifests))
411		for appID := range data.Manifests {
412			appIDs = append(appIDs, appID)
413		}
414		sort.Strings(appIDs)
415		for _, appID := range appIDs {
416			rec := data.Manifests[appID]
417			if rec == nil {
418				// 缺失的清册记录已由 validateManifestConsistency 报告。
419				continue
420			}
421			for _, e := range rec.Entries {
422				ar, ok := data.Archives[e.ID]
423				if !ok || ar == nil {
424					// 清册收录不存在档案等归属问题已由 validateManifestConsistency 报告。
425					continue
426				}
427				items := make([]string, 0, 3)
428				if e.Category != ar.Category {
429					items = append(items, fmt.Sprintf("类别（清册 %q，档案 %q）", e.Category, ar.Category))
430				}
431				if !e.Start.Equal(ar.Start) {
432					items = append(items, fmt.Sprintf("起算日（清册 %s，档案 %s）", e.Start, ar.Start))
433				}
434				if !e.End.Equal(ar.End) {
435					items = append(items, fmt.Sprintf("保管截止日（清册 %s，档案 %s）", e.End, ar.End))
436				}
437				if len(items) > 0 {
438					return fmt.Errorf(
439						"retention: 清册 %s 中档案 %s 的条目与档案登记内容不一致：%s，记录已损坏: %w",
440						appID, e.ID, strings.Join(items, "、"), ErrCorruptState)
441				}
442			}
443		}
444		return nil
445	}
446	
447	// validateManifestProcessing 检查每份已关闭清册是否带有处理日期，以及处理日期
448	// 是否满足办理销毁时同一条到期规则。
449	//
450	// 办理销毁时，只有处理日期不早于名单中任一份档案当时生效的保管截止日才会成功
451	// （截止日当天即到期，见 evaluateArchive），清册条目保存的截止日正是销毁时
452	// 最终生效的期限（已由 validateManifestSnapshots 确认与档案当前登记一致）。
453	// 因此保存的清册还必须满足：
454	//   - 处理日期必须存在：清册缺少处理日期或保存为 null 时，不能把缺失日期当成
455	//     已经办理的销毁日期；
456	//   - 处理日期不能早于任一条目保存的截止日：等于截止日（当天）或晚于截止日
457	//     才合法。期限有过修订的档案按销毁时最终生效并保存到清册里的截止日判断，
458	//     延长、缩短或改回早先用过的日期都一样，绝不按修订办理日期重新挑选另一版期限。
459	//
460	// 缺少处理日期时返回可由 ErrCorruptState 识别的错误并指出清册申请编号；
461	// 处理日期早于某条档案的截止日时同样判为损坏，错误同时指出申请编号、档案编号、
462	// 处理日期与该档案的截止日。一份清册收录多份档案时，只要有一份尚未到期
463	// （例如处理日期等于第一份的截止日、却早于第二份的截止日），整份保管库都
464	// 判为损坏：不会只返回已到期条目的正常记录，也不会把未到期条目略过。校验
465	// 覆盖整个保管库的全部清册，与本次办理名单或查询目标无关；绝不通过改动档案
466	// 或清册（补处理日期、改期限、改销毁标记或条目）消除矛盾。
467	func validateManifestProcessing(data *storeData) error {
468		// map 遍历顺序不稳定，按申请编号排序、条目按清册内保存顺序检查，
469		// 保证错误信息稳定。
470		appIDs := make([]string, 0, len(data.Manifests))
471		for appID := range data.Manifests {
472			appIDs = append(appIDs, appID)
473		}
474		sort.Strings(appIDs)
475		for _, appID := range appIDs {
476			rec := data.Manifests[appID]
477			if rec == nil {
478				// 缺失的清册记录已由 validateManifestConsistency 报告。
479				continue
480			}
481			if rec.ProcessedOn == nil || rec.ProcessedOn.IsZero() {
482				return fmt.Errorf(
483					"retention: 清册 %s 缺少处理日期，不能视为已经办理的销毁清册，记录已损坏: %w",
484					appID, ErrCorruptState)
485			}
486			processedOn := *rec.ProcessedOn
487			for _, e := range rec.Entries {
488				ar, ok := data.Archives[e.ID]
489				if !ok || ar == nil {
490					// 清册收录不存在档案等归属问题已由 validateManifestConsistency 报告。
491					continue
492				}
493				// 条目截止日已由 validateManifestSnapshots 确认与档案最终生效的
494				// 截止日一致，直接按保存在清册里的截止日判断到期。
495				if processedOn.Before(e.End) {
496					return fmt.Errorf(
497						"retention: 清册 %s 的处理日期 %s 早于档案 %s 的保管截止日 %s（截止日当天才算到期），属于提前销毁，记录已损坏: %w",
498						appID, processedOn, e.ID, e.End, ErrCorruptState)
499				}
500			}
501		}
502		return nil
503	}
504	
505	// validateRevisionContinuity 检查每份档案的最初截止日、修订记录与当前截止日
506	// 是否连续对应。
507	//
508	// 正常办理保存的记录必然满足：第一条修订的原截止日等于最初截止日，后续每条
509	// 的原截止日等于上一条的新截止日，最后一条的新截止日等于当前截止日；没有
510	// 修订时最初截止日与当前截止日相同。修订日期仅用于记录办理时间，不决定生效
511	// 先后，因此历史不按修订日期重新排列，只按保存顺序核对衔接；期限被延长、
512	// 缩短或改回早先用过的日期，只要衔接完整都是合法记录。
513	//
514	// 出现断开的修订关系、当前截止日与末次修订的新截止日不符、修订列表中存在
515	// 空记录，或已有修订却缺少最初截止日（不能把当前期限冒充最初期限）时，
516	// 保存内容已无法说明期限如何演变，返回可由 ErrCorruptState 识别的错误，
517	// 并在信息中给出涉及的档案编号；能对应到具体修订时同时给出修订编号。
518	// 校验覆盖整个保管库的全部档案（含已销毁的），与本次办理名单无关。
519	func validateRevisionContinuity(data *storeData) error {
520		// map 遍历顺序不稳定，按档案编号排序后再检查，保证错误信息稳定。
521		archiveIDs := make([]string, 0, len(data.Archives))
522		for id := range data.Archives {
523			archiveIDs = append(archiveIDs, id)
524		}
525		sort.Strings(archiveIDs)
526		for _, id := range archiveIDs {
527			ar := data.Archives[id]
528			if ar == nil {
529				// 缺失的登记记录已由 validateFreezeReleaseRecords 报告。
530				continue
531			}
532			if len(ar.Revisions) == 0 {
533				// 没有修订时最初截止日与当前截止日必须相同
534				// （旧记录缺少最初截止日的情形已在 load 中按登记截止日补齐）。
535				if !ar.InitialEnd.Equal(ar.End) {
536					return fmt.Errorf(
537						"retention: 档案 %s 没有修订记录，但最初截止日 %s 与当前截止日 %s 不一致，记录已损坏: %w",
538						id, ar.InitialEnd, ar.End, ErrCorruptState)
539				}
540				continue
541			}
542			for i, rec := range ar.Revisions {
543				if rec == nil {
544					return fmt.Errorf(
545						"retention: 档案 %s 的修订列表第 %d 条为空记录，记录已损坏: %w",
546						id, i+1, ErrCorruptState)
547				}
548			}
549			if ar.InitialEnd.IsZero() {
550				return fmt.Errorf(
551					"retention: 档案 %s 已有修订记录（首条为 %s）却缺少最初截止日，记录已损坏: %w",
552					id, ar.Revisions[0].ID, ErrCorruptState)
553			}
554			// 按保存顺序逐条核对衔接：每条的原截止日必须等于此前生效的截止日。
555			expected := ar.InitialEnd
556			for _, rec := range ar.Revisions {
557				if !rec.OldEnd.Equal(expected) {
558					return fmt.Errorf(
559						"retention: 档案 %s 的修订 %s 的原截止日 %s 与此前生效的截止日 %s 不衔接，记录已损坏: %w",
560						id, rec.ID, rec.OldEnd, expected, ErrCorruptState)
561				}
562				expected = rec.NewEnd
563			}
564			if !ar.End.Equal(expected) {
565				return fmt.Errorf(
566					"retention: 档案 %s 的当前截止日 %s 与末次修订 %s 的新截止日 %s 不符，记录已损坏: %w",
567					id, ar.End, ar.Revisions[len(ar.Revisions)-1].ID, expected, ErrCorruptState)
568			}
569		}
570		return nil
571	}
572	
573	// validateRevisionIDs 检查成功修订编号在整个保管库内的唯一性，以及与已关闭
574	// 清册申请编号的互不占用。
575	//
576	// 正常办理保存的记录必然满足：每个修订编号在全部档案的修订历史中只出现
577	// 一次，且没有任何编号同时被用作成功销毁申请的编号。同一档案历史中重复
578	// 使用同一编号、不同档案各自保存同号修订（即使两条记录的日期、原因等
579	// 内容完全相同），或修订编号与一份已关闭清册的申请编号相同，都会使
580	// “按编号重试取回唯一一条修订”无法成立，返回可由 ErrCorruptState 识别
581	// 的错误：绝不合并重复记录，也不挑选其中一条继续使用。
582	//
583	// 错误信息给出冲突的修订编号与涉及的档案编号；跨档案重复时同时给出两份
584	// 档案，与清册冲突时给出清册的申请编号。校验覆盖整个保管库的全部档案
585	// （含已销毁的），与本次办理名单或查询目标无关。修订编号为空白同样不能
586	// 作为成功记录存在，一并按损坏处理。
587	func validateRevisionIDs(data *storeData) error {
588		owners := make(map[string]string)
589		// map 遍历顺序不稳定，按档案编号排序后再检查，保证错误信息稳定。
590		archiveIDs := make([]string, 0, len(data.Archives))
591		for id := range data.Archives {
592			archiveIDs = append(archiveIDs, id)
593		}
594		sort.Strings(archiveIDs)
595		for _, id := range archiveIDs {
596			ar := data.Archives[id]
597			if ar == nil {
598				// 缺失的登记记录已由 validateFreezeReleaseRecords 报告。
599				continue
600			}
601			for _, rec := range ar.Revisions {
602				if rec == nil {
603					// 空记录已由 validateRevisionContinuity 报告。
604					continue
605				}
606				if strings.TrimSpace(rec.ID) == "" {
607					return fmt.Errorf(
608						"retention: 档案 %s 的修订历史中存在没有编号的修订记录，记录已损坏: %w",
609						id, ErrCorruptState)
610				}
611				if owner, ok := owners[rec.ID]; ok {
612					if owner == id {
613						return fmt.Errorf(
614							"retention: 修订编号 %s 在档案 %s 的历史中出现多条记录，保存记录已损坏: %w",
615							rec.ID, id, ErrCorruptState)
616					}
617					return fmt.Errorf(
618						"retention: 修订编号 %s 同时保存在档案 %s 与档案 %s 的修订历史中，保存记录已损坏: %w",
619						rec.ID, owner, id, ErrCorruptState)
620				}
621				owners[rec.ID] = id
622			}
623		}
624		// 修订编号与销毁申请编号互不占用：任何已关闭清册的申请编号都不能
625		// 同时是一条已保存修订的编号。申请编号按排序遍历，错误信息稳定。
626		appIDs := make([]string, 0, len(data.Manifests))
627		for appID := range data.Manifests {
628			appIDs = append(appIDs, appID)
629		}
630		sort.Strings(appIDs)
631		for _, appID := range appIDs {
632			if owner, ok := owners[appID]; ok {
633				return fmt.Errorf(
634					"retention: 档案 %s 的修订编号 %s 与已关闭清册的申请编号 %s 相同，保存记录已损坏: %w",
635					owner, appID, appID, ErrCorruptState)
636			}
637		}
638		return nil
639	}
640	
641	// save 原子地写入状态：先写同目录临时文件并刷盘，再 rename 替换，最后刷目录。
642	// 写入过程中崩溃不会留下半截状态，旧文件保持完好。
643	func (s *Store) save(data *storeData) error {
644		buf, err := json.MarshalIndent(data, "", "  ")
645		if err != nil {
646			return fmt.Errorf("retention: 状态编码失败: %w", err)
647		}
648		tmp, err := os.CreateTemp(s.dir, ".retention-state-*.tmp")
649		if err != nil {
650			return fmt.Errorf("retention: 无法创建临时状态文件: %w", err)
651		}
652		tmpName := tmp.Name()
653		cleanup := func() { _ = os.Remove(tmpName) }
654		if _, err := tmp.Write(buf); err != nil {
655			tmp.Close()
656			cleanup()
657			return fmt.Errorf("retention: 写入状态失败: %w", err)
658		}
659		if err := tmp.Sync(); err != nil {
660			tmp.Close()
661			cleanup()
662			return fmt.Errorf("retention: 刷盘状态失败: %w", err)
663		}
664		if err := tmp.Close(); err != nil {
665			cleanup()
666			return fmt.Errorf("retention: 关闭状态文件失败: %w", err)
667		}
668		if err := os.Rename(tmpName, s.statePath()); err != nil {
669			cleanup()
670			return fmt.Errorf("retention: 替换状态文件失败: %w", err)
671		}
672		// 刷目录，确保 rename 在崩溃后仍然落盘。
673		if dir, err := os.Open(s.dir); err == nil {
674			_ = dir.Sync()
675			_ = dir.Close()
676		}
677		return nil
678	}
679	
680	// mutate 在跨进程排他锁内重读状态、办理变更，仅在全部校验通过后写回。
681	// fn 返回错误时绝不写盘，磁盘上的已有记录不受影响。
682	func (s *Store) mutate(fn func(*storeData) error) error {
683		s.opMu.Lock()
684		defer s.opMu.Unlock()
685		unlock, err := s.lock()
686		if err != nil {
687			return err
688		}
689		defer unlock()
690		data, err := s.load()
691		if err != nil {
692			return err
693		}
694		if err := fn(data); err != nil {
695			return err
696		}
697		return s.save(data)
698	}
699	
700	// view 在共享锁内重读状态并执行只读查询。
701	func (s *Store) view(fn func(*storeData) error) error {
702		s.opMu.RLock()
703		defer s.opMu.RUnlock()
704		unlock, err := s.rlock()
705		if err != nil {
706			return err
707		}
708		defer unlock()
709		data, err := s.load()
710		if err != nil {
711			return err
712		}
713		return fn(data)
714	}
715

