30	func TestOpenRejectsCorruptStateFile(t *testing.T) {
31		corrupt := map[string]string{
32			"零字节文件":      "",
33			"只有空白":       "  \n\t \n",
34			"内容为 null":   "null",
35			"null 带空白":   " \n null \n",
36			"对象后拼接第二个值":  `{"version":1,"archives":{},"manifests":{}} {"version":1}`,
37			"对象后拼接 null": `{"version":1,"archives":{},"manifests":{}} null`,
38			"对象后夹非法文字":   `{"version":1,"archives":{},"manifests":{}} 这不是合法JSON`,
39			"半截 JSON":    `{"version":1,"archives":{`,
40			"顶层不是对象":     `[{"version":1}]`,
41		}
42		for name, content := range corrupt {
43			t.Run(name, func(t *testing.T) {
44				dir := t.TempDir()
