89	// 保管库打开后文件才损坏：下一次查询与办理都必须明确失败，
90	// 不能给出正常结论，也不能改动原文件。
91	func TestCorruptionAfterOpenFailsSubsequentOperations(t *testing.T) {
92		dir := t.TempDir()
93		s, err := Open(dir)
94		if err != nil {
95			t.Fatal(err)
96		}
97		defer s.Close()
