153		}
154	
155		// 恢复合法内容后：失败的销毁申请没有留下清册，申请编号仍可正常使用。
156		writeStateFile(t, dir, original)
157		if _, found, err := s.GetManifest("APP-1"); err != nil || found {
158			t.Fatalf("失败的销毁申请不应留下清册: found=%v err=%v", found, err)
159		}
160		if _, err := s.Destroy(DestructionRequest{
161			ApplicationID: "APP-1", ProcessedOn: MustParseDate("2025-01-10"), ArchiveIDs: []string{"A-1"},
162		}); err != nil {
163			t.Fatalf("恢复后同一申请编号应能正常办理: %v", err)
164		}
165	}
