223	// 保管库打开后保存内容才出现清册处理日期问题：缺处理日期或处理日期被改成
224	// 早于截止日，下一次使用有效输入的查询历史、取回清册、销毁前核对与各项办理
225	// 都必须按整库记录损坏失败——即使操作的是不在该清册中的无关档案——不返回
226	// 正常结果或部分核对报告，不产生业务变更，原保存内容保持原样。
227	func TestManifestProcessingCorruptionAfterOpenFailsAllOperations(t *testing.T) {
228		cases := map[string]func(map[string]any){
229			"清册处理日期被删除": func(doc map[string]any) {
