266				}
267	
268				// 已打开实例：即使操作与该清册无关的 A-2，也必须按整库损坏失败。
269				if h, found, err := s.History("A-2"); !errors.Is(err, ErrCorruptState) || found || h.ID != "" {
270					t.Fatalf("损坏后查询无关档案也必须失败且无结论: found=%v err=%v", found, err)
271				}
