273					t.Fatalf("损坏后 History 必须失败且不得给出正常销毁历史: found=%v err=%v", found, err)
274				}
275				if m, found, err := s.GetManifest("APP-1"); !errors.Is(err, ErrCorruptState) || found || m.ApplicationID != "" {
276					t.Fatalf("损坏后 GetManifest 必须失败: found=%v err=%v %+v", found, err, m)
277				}
