304					RevisionID: "R-9", ArchiveID: "A-2",
305					OriginalEnd: MustParseDate("2025-06-30"), NewEnd: MustParseDate("2026-06-30"),
306					RevisedOn: MustParseDate("2025-06-01"), Reason: "延期",
307				}); !errors.Is(err, ErrCorruptState) {
