319	// 提前销毁的损坏恢复为合法内容后，合法记录的登记、冻结解除、期限修订与申请
320	// 复用行为沿用现有功能，不被新校验误伤。
321	func TestRestoredValidStateAfterProcessingCorruptionWorks(t *testing.T) {
322		dir := t.TempDir()
323		s, err := Open(dir)
324		if err != nil {
325			t.Fatal(err)
326		}
327		defer s.Close()
328		reg(t, s, "A-1", "合同", "2020-01-01", "2025-01-10")
329		reg(t, s, "A-2", "凭证", "2020-01-01", "2025-06-30")
330		if _, err := s.Destroy(DestructionRequest{
331			ApplicationID: "APP-1", ProcessedOn: MustParseDate("2025-01-10"), ArchiveIDs: []string{"A-1"},
332		}); err != nil {
333			t.Fatal(err)
334		}
335	
336		// 改成提前销毁，确认整库不可用。
337		rewriteState(t, dir, func(doc map[string]any) {
338			doc["manifests"].(map[string]any)["APP-1"].(map[string]any)["processed_on"] = "2025-01-09"
339		})
340		if _, found, err := s.History("A-2"); !errors.Is(err, ErrCorruptState) || found {
341			t.Fatalf("提前销毁状态下应整库损坏: found=%v err=%v", found, err)
342		}
343	
344		// 恢复为合法处理日期（截止日当天）后，业务恢复正常。
345		rewriteState(t, dir, func(doc map[string]any) {
346			doc["manifests"].(map[string]any)["APP-1"].(map[string]any)["processed_on"] = "2025-01-10"
347		})
348		m, found, err := s.GetManifest("APP-1")
349		if err != nil || !found || !m.ProcessedOn.Equal(MustParseDate("2025-01-10")) {
350			t.Fatalf("恢复后清册应可取回: found=%v err=%v %+v", found, err, m)
351		}
352		// 相同申请仍按幂等取回原清册。
353		replay, err := s.Destroy(DestructionRequest{
354			ApplicationID: "APP-1", ProcessedOn: MustParseDate("2025-01-10"), ArchiveIDs: []string{"A-1"},
355		})
356		if err != nil || replay.ApplicationID != "APP-1" {
357			t.Fatalf("恢复后相同申请应取回原清册: %+v err=%v", replay, err)
358		}
359		// 未销毁档案的冻结解除、期限修订与新申请销毁不受影响。
360		if err := s.Freeze(FreezeInput{ArchiveID: "A-2", FreezeID: "F-1", Reason: "诉讼", FrozenOn: MustParseDate("2025-06-01")}); err != nil {
361			t.Fatalf("恢复后应能新增冻结: %v", err)
362		}
363		if err := s.Release(ReleaseInput{ArchiveID: "A-2", FreezeID: "F-1", Reason: "结案", ReleasedOn: MustParseDate("2025-06-02")}); err != nil {
364			t.Fatalf("恢复后应能解除冻结: %v", err)
365		}
366		if _, err := s.Revise(ReviseInput{
367			RevisionID: "R-1", ArchiveID: "A-2",
368			OriginalEnd: MustParseDate("2025-06-30"), NewEnd: MustParseDate("2026-06-30"),
369			RevisedOn: MustParseDate("2025-06-03"), Reason: "延期",
370		}); err != nil {
371			t.Fatalf("恢复后应能修订期限: %v", err)
372		}
373		if _, err := s.Destroy(DestructionRequest{
374			ApplicationID: "APP-2", ProcessedOn: MustParseDate("2026-06-30"), ArchiveIDs: []string{"A-2"},
375		}); err != nil {
376			t.Fatalf("恢复后应能用新申请办理销毁: %v", err)
377		}
378	}
